internal object DuaBrxDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("गोदान अखाफोर नुना।", "ऐ अल्लाह, बे अखाफोरा बोर, फोथायथि, रैखाथि आरो इस्लामजों जोंनि सायाव ओंखारनो हो। (अखाफोर,) आंनि इसोर आरो नोंनि इसोरआ अल्लाह।", "गोदान अखाफोर नुजाखांनायनि उनाव।", "मोनफ्रोमबो गोदान दाननि थाखाय सुन्नत दुआ।"),
        "dua_janaza_adult" to DuaText("जनजा आरज (बैसोगोरा)", "ऐ अल्लाह, जोंनि जिउ थानाय आरो जोंनि थैनाय, जायफोरा दं आरो जाय गैया, जोंनि लायमोन आरो जोंनि बुज़ु, जोंनि हौवाफोर आरो जोंनि आयजोफोरखौ क्षमा खालाम। ऐ अल्लाह, जोंनि गेजेराव जायखौ नों थांना दोन, बिखौ इस्लामनि सायाव थांना लाखि, आरो जोंनि गेजेराव जायखौ नों थैयो, बिखौ फोथायनायाव थैनो हो।", "गोथै सावनायनि आरज गाबनायनि थामथि तकबीरनि उनाव।", "सासे थैनाय बैसोगोराफोरनि थाखाय सुन्नह दुआ।"),
        "dua_janaza_child" to DuaText("जनजा आरज (गथ')", "ऐ अल्लाह, बिखौ जोंनि थाखाय सिगांसिन (आरो थाग्रा) खालाम, बिखौ जोंनि थाखाय बान्था आरो धोन खालाम, आरो बिखौ जोंनि थाखाय सासे मददगिरि खालाम जायनि मददखौ गनायनाय जायो।", "सासे गथ'नि गोथै सावनायाव आरज गाबनाय जायो (सासे हिनजावसानि थाखाय'इज'अलहा'बुंनाय जायो)।", "हनाफीफोरजों सुन्नह दुआआ सोलियो।"),
        "dua_mayyit_awf" to DuaText("थैनायफोरनि थाखाय गुवारै दुआ।", "ऐ अल्लाह, बिखौ क्षमा खालाम, बिनि सायाव अननाय हो, बिखौ मोजां खालाम आरो बिखौ क्षमा खालाम। बिनि आजावनायखौ मान गोनां आरो बिनि गोथै खामफाखौ गुवार खालाम, बिखौ दै, बरफ आरो अखाफोरजों सुयो, आरो बिखौ पापफोरनिफ्राय साफा खालाम जेरै मोनसे गुफुर जिखौ मैलानिफ्राय साफा खालामनाय जायो।", "गोथै सावनि आरज गाबनायाव एबा थैनाय सुबुंफोरनि थाखाय।", "अवफ इब्न मलिक (र.) आ लुबैदोंमोन दि बियो बै थैनाय सुबुंमोन।"),
        "dua_visiting_graves" to DuaText("द ग्रेभ्सखौ नायहैनाय", "ऐ ईमान गोनां आरो बे न'फोरनि मुस्लिम थाग्राफोर, नोंनाव गोजोन था। जोंबो, जुदि अल्लाहआ गोसो होयो, नोंजों लोगो जागोन। आं जोंनि आरो नोंनि थाखाय अल्लाहखौ मोजांनि थाखाय आरज गाबनायसै।", "जब्रायाव हाबनायाव।", "गोथै खामफाफोराव दावबायनाया सासेखौ थैनाय आरो उननि गोसोखांहोयो।"),
        "dua_closing_eyes" to DuaText("थैनायफोरनि मेगनखौ बन्द खालामनाय समाव।", "ऐ अल्लाह, (मुं) खौ बावगार, लामा दिन्थिग्राफोरनि गेजेराव गावनि थाखोखौ गोजौ खालाम, जायफोरखौ बियो नागारदों, बिसोरनि गेजेराव बिथांनि उनमोनगिरि जा। हे मुलुगनि इसोर, नोंखौ आरो बिथांखौ बावगार, बिथांनि गोथै खामफाखौ गुवार खालाम आरो बेखौ सोरांजों आबुं खालाम।", "थैनायनि मेगनखौ बन्द खालामनाय समाव (बिथांनि मुंखौ मुंख'नाय)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा आबु सलामाह (रा.) नि थाखाय बे दुआखौ बानायदोंमोन।"),
        "dua_condolence" to DuaText("दुखु होनाय (ताजियाह)", "थारैनो अल्लाहनो जाय बिथाङा लादोंमोन आरो जाय बिथाङा होदोंमोन बियो बिथांनिनो, आरो बिथांनि खाथियाव गासैबो जिनिसनि मोनसे थि सम थायो, बेनिखायनो सहायना था आरो बान्था मोननो मिजिं था।", "सासे थैनायनि उनाव मोनसे नखरनो दुखु होनाय।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे खौरांखौ गावनि फिसाजोनो दैथायहरदोंमोन।"),
        "dua_placing_in_grave" to DuaText("थैनायखौ गोथै खथायाव दोननाय।", "अल्लाहनि मुंजों आरो अल्लाहनि पैगंबरनि लामायाव।", "जेब्ला थैनायखौ गोथै खथायाव गाहायाव लाबोयो।", "गोथै सावनायनि सुन्नत दुआ।"),
        "dua_sneezing" to DuaText("हासुनाय।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय।-अल्लाहआ नोंखौ अननाय हो।-अल्लाहआ नोंखौ लामा दिन्थिहो आरो नोंनि हाबाफोरखौ थि खालामहो।", "हासुनाय समाव खोनासंगिरिआ'यारहामुकल्ला'बुङो, बिनि उनाव हासुनायानो फिन बुङो।", "बेयो सासे मुस्लिमनि गुबुन सासे मुस्लिमनि सायाव मोनजानाय मोनहोग्रा मोन।"),
        "dua_toilet_enter" to DuaText("खिख'रंआव हाबना।", "अल्लाहनि मुंजों। ऐ अल्लाह, आं नोंनाव हौवा आरो हिनजाव गाज्रि जिनफोरनिफ्राय शरण नागिरो।", "खिख'बाथरुमआव आगान होनायनि सिगां आगसि आथिंजों।", "बिस्मिल्लाया जिन्न आरो सुबुंनि गेजेराव मोनसे फैसालि जायो।"),
        "dua_toilet_exit" to DuaText("खिख'रंखौ नागारनाय।", "(अ'अल्लाह) आं नोंखौ क्षमा खालाम।", "जेब्ला आगदा आथिंजों खिख'ख'निफ्राय ओंखारबोयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा खिख'निफ्राय ओंखारनायाव बे बाथ्रा बुंदोंमोन।"),
        "dua_thanking" to DuaText("सोरबा सासेखौ थैंकिं खालाम।", "अल्लाहआ नोंखौ मोजां बान्था हो।", "जेब्ला सोरबा नोंथांखौ मदद खालामो।", "जाय बेबादि बुङो बियो आबुङै गावनि बाखनायनायखौ फोरमायदोंमोन।"),
        "dua_love_for_allah" to DuaText("जेब्ला सोरबा बुङो'आइ लाभ यु फर अल्लाह'।", "बियो (अल्लाह), जायनि थाखाय नों आंखौ मोजां मोनो, नोंखौ मोजां मोनो।", "जेब्ला सोरबा बुङो'आं नोंखौ अल्लाहनि थाखाय मोजां मोनो'।", "सुन्नाया अल्लाहनि थाखाय मोजां मोननायाव फिन होयो।"),
        "dua_seeing_muslim_smile" to DuaText("हामलायनाय (सलाम)।", "नोंनि सायाव गोजोन आरो अल्लाहनि अननाय आरो बिथांनि बोरफोर था।", "जेब्ला सासे मुसलमानखौ लोगो मोनो।", "आबुं सालाम बुंनाया थामजि मोजां खामानिफोर आरजियो।"),
        "dua_dressing" to DuaText("जि-जोमनाय।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय, जाय आंनो बेखौ गानदोंमोन आरो आंनि फारसेनिफ्राय जेबो गोहो एबा गोहो गैयालासेनो बेखौ होदोंमोन।", "जेब्ला सि-जोम गाननाय जायो।", "थांनाय पापफोरखौ बावसोमनायनि गोजोन खौरां।"),
        "dua_rooster_donkey" to DuaText("मासे दावखोब एबा गधाखौ खोनानाय।", "ऐ अल्लाह, आं नोंखौ नोंनि अनथोब (दाव) नि बागै सोङो।-आं शापित (गाराय) शयताननिफ्राय अल्लाहनि सिङाव आश्रय नागिरो।", "मासे मासे दावखौ खोनानायानो अल्लाहनि अनथोबखौ सोङो; मासे गांसोनि गांसोखौ खोनानायानो शयताननि शरण लायो।", "मासे दावदैआ सासे फेरेशताखौ नुयो आरो मासे गांसोआ सासे शेदांखौ।"),
        "dua_something_liked" to DuaText("माबा बा बाख्नायजाथाव नुजानाय (गाज्रि मेगननि बेरेखायै)", "अल्लाहआ जायखौ लुबैदों। ऐ अल्लाह, बिखौ बोर हो।", "सोरबा सासेनि बाखनायथाव माबा मोनसेखौ नुनानै, बोरनि थाखाय आरज गाब।", "बोरनि थाखाय आरज गाबनाया गाज्रि मेगनखौ होबथायो।"),
        "dua_sell_buy_debt_repaid" to DuaText("जेब्ला दाहारखौ सुख'नाय जायो", "अल्लाहआ नोंखौ नोंनि न'खर आरो धोनआव बोर होहो।", "दाहार होग्रानि थाखाय जेब्ला दाहारखौ सुख'नाय जायो।", "दाहारखौ फिन मोननाया जादों थैंकस आरो फिन होफिन्नाय।"),
        "dua_talbiyah" to DuaText("तालबिया", "आं बेहाय दं, ऐ अल्लाह, बेहाय आं। बेहाय आं दं, नोंहा रावबो बाहागोआरि गैया, बेहाय आं दं। थारैनो गासिबो बाख्नायनायनाय, बोरफोर आरो रायजोआ नोंनि। नोंहा रावबो बाहागोआरि गैया।", "इहरामआव हाबखांनायनि उनाव गोबारै।", "हज आरो उमरानि नेरसोन।"),
        "dua_yamani_hajar" to DuaText("रुकन यामनी आरो हजार असवादनि गेजेराव", "जोंनि इसोर, जोंनो बे मुलुगाव मोजां आरो जोबनायाव मोजां हो आरो जोंनो अरनि साजानिफ्राय रैखा खालाम।", "तवाफआव, येमेनि कर्नार आरो ब्लेक स्टोननि गेजेराव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा तवाफनि बे जायगायाव बेखौ फरायदोंमोन।"),
        "dua_safa_marwa" to DuaText("साफा आरो मारवाहआव", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो आरो बिथांनिनो बाख्नायनायनाय, आरो गासिबो जिनिसनि सायाव बिथांनिनो गोहो दं। अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया; बिथाङा गावनि बावसोमनायखौ आबुं खालामदोंमोन, गावनि बान्दाखौ हेफाजाब होदोंमोन आरो गलायमोनदेरफोरखौ सोलिदोंमोन।", "साफायाव गाखोनाय आरो किब्लाहखौ मोखां खालामनाय (खेबथाम)।", "साफा आरो मारवाहआव पैगंबरनि दिकर।"),
        "dua_arafah" to DuaText("आराफानि साननि साबसिन दुआ।", "अल्लाहनि अनगा रावबो फुजिजानायनि मोन्थाइ गैया, सोलायै, बाहागोआरि गैयालासे। बिथांनिनो रायजो दं आरो बिथांनिनो बाख्नायनायनाय आरो बिथाङा गासैबो जिनिसनि सायाव गोहो दं।", "आराफानि साना-साबसिन दुआ।", "साबसिन दुआआ आराफाहनि साननि दुआ, आरो साबसिन सोदोबफोरा बेफोर।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तश्रीक", "अल्लाहआ देरसिन, अल्लाहआ देरसिन। अल्लाहनि अनगा रावबो इसोर गैया। अल्लाहआ देरसिन, अल्लाहआ देरसिन आरो गासिबो बाख्नायनाया अल्लाहनि थाखाय।", "9 धुल-हिज्जानि फजरनिफ्राय 13 धुल-हिज्जानि असरसिम मोनफ्रोमबो गोनांथार आरज गाबनायनि उनाव।", "हनाफीफोरनि बायदिब्ला, आली आरो इब्न मसूद (रा.) निफ्राय वजीबखौ फोरमायदोंमोन।"),
        "dua_zamzam" to DuaText("जामजाम लों।", "ऐ अल्लाह, आं नोंखौ मुलामफा गोनां गियान, गोबां राहा आरो गासैबो बेरामनिफ्राय फाहामनायनि थाखाय सोङो।", "जामजाम लोंनायाव, नों जाय गोसो हो बेनि थाखाय दुआ बानाय।", "जमजमआ जायखिनि थाखाय लोंजायो (इब्न माजाह 3062) बिनि थाखाय।"),
        "dua_q_ma_khalaqta_batila" to DuaText("सोरजिनायनि सायाव सानना नाय।", "जोंनि इसोर, नों बे गासिबोखौ खहा खालामै बानायाखै। नोंनो गोग्गानाय, बेनिखायनो जोंफोरखौ अरनि साजानिफ्राय रैखा खालाम।", "सोरगो आरो बुहुमनि सोरजिलायखौ नायग्रा सुबुंफोरनि दुआ।", "बुजिनो हानाय सुबुंफोरनि दुआ (उलुल-अलबाब)।"),
        "dua_q_sami_na_munadiyan" to DuaText("जों फोथायनो थाखाय लिंहरग्राखौ खोनानायसै।", "जोंनि इसोर, जों सासेखौ फोथायनो लिंहरग्राखौ खोनानायसै, बियो बुङो,'नोंनि इसोरखौ फोथाय', आरो जों फोथायदोंमोन। जोंनि इसोर, जोंनि पापफोरखौ क्षमा खालाम, जोंनि गाज्रि खामानिखौ बोखार आरो जोंनि थाखाय गोथारफोरजों लोगोसे जिउ खांहो।", "फोथायनायनि थाखाय मोनसे दुआ आरो गोथार सुबुंफोरनि गेजेराव थैनाय।", "बावसोमनाय आरो मोनसे मोजां जोबनायनि थाखाय मोनसे दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("नों जाय बावसोमदोंमोन बेखौ हो।", "ऐ जोंनि इसोर, नों गावनि रसूलनि गेजेरजों जोंजों जाय समाय होदोंमोन, बिखौ हो आरो जोनोमनि सानाव जोंजों मानहानि खालाम। थारैनो नों गावनि बावनायखौ सिफायनो नाङा।", "फिन फिन फिन फिन फिन फिन फिन फिननाय सानाव लाजिनिफ्राय रैखा ला।", "उनाव मान बावना।"),
        "dua_q_israfana" to DuaText("जोंनि बांद्रायखौ बावगार।", "जोंनि इसोर, जोंनि पापफोरखौ आरो जोंनि हाबाफोराव जोंनि बांद्रायखौ क्षमा खालाम, जोंनि आथिंखौ गोख्रों खालाम आरो फोथायै सुबुंफोरनि बेरेखायै जोंनि मदद खालाम।", "सिगांनि पैगंबरफोरनि लोगोफोरनि दुआ।", "दिदोमथि आरो बावसोमनायनि थाखाय मोनसे दुआ।"),
        "dua_q_jamiun_nas" to DuaText("नों सुबुंथिखौ ज'खालामगोन।", "जोंनि इसोर, नों थारैनो मानसिफोरखौ बै सानाव ज'खालामगोन, जायनि बागै जेबो सन्देह गैया। थारैनो अल्लाहआ गावनि बावसोमनायखौ सिफायनो हाया।", "फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिन फिननो।", "गियानाव गोख्रों बिथा थानाय सुबुंफोरनि दुआ।"),
        "dua_q_maash_shahidin" to DuaText("साखिफोरनि गेजेराव जोंनो लिर।", "जोंनि इसोर, जों फोथायो, बेनिखायनो साखिफोरनि गेजेराव लिर।", "जाय सैथोखौ सिनायदोंमोन आरो फोथायदोंमोन, बिसोरनि दुआ।", "गावनि फोथायनायखौ गनायनायनि थाखाय मोनसे दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("गोरोन्थि खालामग्राफोरजों नङा।", "जोंनि इसोर, जोंफोरखौ गोरोनथि खालामग्रा सुबुंफोरजों थाफादेर।", "अल-आराफनि सुबुंफोरनि दुआ।", "गोरोनथि खालामग्राफोरनि खाफानिफ्राय रैखा ला।"),
        "dua_q_tawaffana_muslimin" to DuaText("मुसलमान महरै सहायनाय आरो थैनाय।", "जोंनि इसोर, जोंनि सायाव सहायथि हो आरो मुसलमान महरै जोंखौ थैनो हो।", "फार'ननि जादुगिरिफोरनि दुआ जेब्ला बिसोरो फोथायो।", "आनजाद नायनायाव सहायनाय आरो फोथायनायाव जोबनाय।"),
        "dua_q_la_tajalna_fitnah" to DuaText("अनागारिफोरनि थाखाय मोनसे बिसिबां नङा।", "जों अल्लाहनि सायाव सोनारो। जोंनि इसोर, बेसोर गाज्रि खालामग्रा सुबुंफोरनि थाखाय जोंनि सायाव मोनसे आनजाद खालाम आरो नोंनि अननायजों फोथायनो हायै सुबुंफोरनिफ्राय रैखा खालाम।", "मुसा (ए. एस.) नि सुबुंफोरनि दुआ।", "अनागारि आरो अनागारिफोरनिफ्राय रैखा खालामनायनि थाखाय मोनसे दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("क्षमा खालामनायनि थाखाय नूह (ए. एस.) नि दुआ।", "आंनि इसोर, आं नोंखौ बै जिनिसनि थाखाय सोदेरनायनिफ्राय नोंनि सिङाव आश्रय नागिरो जायनि बागै आंहा जेबो गियान गैया। आरो जेब्लासिम नों आंखौ क्षमा खालामाखै आरो आंखौ अननायाखै, अब्लासिम आं खहा जानायफोरनि गेजेराव जागोन।", "पैगंबर नूह (अ. स.) नि उनदाहा।", "मोजां आदबजों सोंनायनि मोनसे सोलोंसा।"),
        "dua_q_mudkhala_sidq" to DuaText("सैथोनि हाबग्रा आरो ओंखारग्रा", "आंनि इसोर, आंखौ सैथोजों लोगोसे हाबहोनो आरो सैथोजों ओंखारहोनो, आरो नोंनिफ्राय आंनो मोनसे हेफाजाब होग्रा गोहो हो।", "गोदान खामानियाव हाबनायनि सिगां न'एबा जायगायाव हाब।", "दुआआ हिज्रानि समाव पैगंबर सल्लल्लाहु अलैहि वस्लमनो फोरोंदोंमोन।"),
        "dua_q_la_tadharni_fardan" to DuaText("ज़कारियानि दुआ (एएस)-आंखौ हारसिङै नागार।", "आंनि इसोर, आंखौ हारसिङै नागारनाङा, आरो नोंनो साबसिन उनमोनगिरिफोर।", "गथ'फोरखौ नागिरग्राफोरनि थाखाय।", "बे दुआनि गेजेरजों अल्लाहआ याह्या (ए. एस.) होदोंमोन।"),
        "dua_q_munzalan_mubarakan" to DuaText("मोनसे बोरगोनां ल्यान्डिं जायगा।", "आंनि इसोर, आंनो मोनसे बोरगोनां ओंखारग्रा जायगायाव ओंखारनो हो, आरो नों बैसोरनि गेजेराव साबसिन जाय हायाव लाबोयो।", "जेब्ला गोदान न'आव थाङो एबा बबेयावबा थाथ'यो-नूह (एएस) नि दुआ।", "गोदान जायगायाव बोर होनायनि थाखाय दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("जों फोथायो, बेनिखायनो नोंखौ बावगार।", "जोंनि इसोर, जों फोथायो, बेनिखायनो नोंखौ क्षमा खालाम आरो जोंनि सायाव अननाय हो आरो नोंनो साबसिन अनजाथाव।", "अल्लाहनि गोथार बान्दाफोरनि दुआ।", "बावसोमनाय आरो अननायनि थाखाय मोनसे आबुं दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("जाहान्नामनि साजाखौ गारहर।", "ऐ जोंनि इसोर, जोंनिफ्राय जाहान्नामनि साजाखौ एंगार। थारैनो बेनि सजाया जेब्लाबो सोलिबोनाय। थारैनो, बेयो मोनसे गाज्रि थाखुलि आरो थाग्रा जायगा।", "बयनिख्रुइबो बांसिन अनग्रानि ('इबादत-आर-रहमान) बान्दाफोरनि दुआ।", "जाहान्नामनिफ्राय रैखा मोननो थाखाय मोनसे कुरानिक दुआ।"),
        "dua_q_hab_li_hukman" to DuaText("इब्राहिमनि दुआ (ए. एस.)-गियान आरो जान्ना", "आंनि इसोर, आंनो गियान हो आरो गोथारफोरजों लोगोसे था, उननि फोलेरफोरनि गेजेराव आंनो मोनसे मान गोनां मुंख'नाय हो, आरो आंखौ अनंदानि बिबारबाननि उनमोनगिरिफोरनि गेजेराव बानाय।", "गियाननि थाखाय सोंनाय, धोरोमारि आरो सोरगोनि कम्पानी।", "इब्राहिम (ए. एस.) नि मोनसे आबुं दुआ।"),
    )
}
